(function(){'use strict';
/* JAH The Analytical Chemistry Signature generator — jahdb-analytical-chemistry-signature-1.0.
   Property of Justin Addam Higgins (JAH).
   Deterministic: same seed, same record. */
var PREFIX='JAH-ANALCS-';
var FIELDS=["Foundations","Compounded","Advanced"];
var TOPICS=[{"tier": "Foundations", "g": "Fundamentals", "title": "What Is Analytical Chemistry", "desc": "Analytical chemistry answers two questions: what is present (qualitative) and how much (quantitative). Every drug tablet, environmental water sample, and forensic exhibit passes through analytical methods - the field is chemistry's measurement science.\nIt divides into classical methods (gravimetry, titrimetry - wet chemistry with balances and burettes) and instrumental methods (spectroscopy, chromatography, electroanalysis). The modern lab is instrumental, but every instrument is calibrated against classical standards - the traceability chain.", "how": "Define the analytical problem: analyte, matrix, required detection limit, and accuracy. Choose classical for high accuracy at macro levels, instrumental for trace levels and speed. Validate any method for its intended use before reporting results that decisions depend on.", "keys": ["Qualitative: what; quantitative: how much.", "Classical (wet) vs instrumental methods.", "Every measurement traces to standards.", "Detection limit must beat the required level.", "Methods are validated before use."], "reqs": ["Defined analyte and matrix.", "Required accuracy and detection limit.", "Calibrated instruments."], "stds": ["Results with uncertainty estimates.", "Traceability to certified standards."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Choose method class by required detection limit.\"\"\"\ndef method_class(lod_needed_ppm):\n    return \"instrumental\" if lod_needed_ppm < 1 else \"classical or instrumental\"\nfor lod in (0.001, 0.1, 100):\n    print(f\"  need {lod} ppm -> {method_class(lod)}\")\n"}, {"tier": "Foundations", "g": "Fundamentals", "title": "The Analytical Process: Sampling to Reporting", "desc": "Analysis is a chain: define the problem, choose a method, sample representatively, prepare the sample, measure, process data, and report with uncertainty. The chain is only as strong as its weakest link - and that link is usually sampling.\nA gold ore assayed perfectly from a bad grab sample is worthless; Gy's sampling theory quantifies how heterogeneity demands sample mass. Every step - dissolution, dilution, separation - can add bias or contamination, so blanks and standards travel with the samples.", "how": "Design sampling from heterogeneity: more heterogeneous means larger or more numerous increments. Document chain of custody for legal samples. Run blanks (contamination check), duplicates (precision), and spiked/standard samples (bias check) with every batch.", "keys": ["Sampling is usually the weakest link.", "Heterogeneity demands sample mass (Gy theory).", "Blanks check contamination; spikes check bias.", "Chain of custody for forensic/legal samples.", "Report numbers with their uncertainty."], "reqs": ["Representative sampling plan.", "QC samples in every batch.", "Documented procedures."], "stds": ["Sampling per Gy theory or standard protocols.", "Uncertainty reported with coverage factor."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Gy P. Sampling for Analytical Purposes. Wiley; 1998."], "demo": "#!/usr/bin/env python3\n\"\"\"Sampling mass scales with heterogeneity (toy model).\"\"\"\ndef mass_needed(heterogeneity):\n    return 10 * heterogeneity**2\nfor h in (1, 2, 5):\n    print(f\"  heterogeneity {h}: relative mass {mass_needed(h):.0f} g\")\n"}, {"tier": "Foundations", "g": "Data", "title": "Units, Significant Figures, and Error", "desc": "A measurement without uncertainty is a rumor: 10.0 mL (±0.02) from a burette differs from 10 mL (±1) from a graduated cylinder. Significant figures encode precision - the burette reading 10.00 mL claims hundredths; the cylinder cannot.\nSystematic error (bias) shifts all results one way - a miscalibrated balance; random error scatters them - reading noise. Blunders are neither; they are mistakes to eliminate. Error propagation tracks how uncertainties combine through calculations.", "how": "Report significant figures honestly: the result's last digit is the first uncertain one. Distinguish bias (correct by calibration/blanks) from random error (reduce by replication). Propagate uncertainties: for addition/subtraction use absolute uncertainties; for multiplication/division use relative ones.", "keys": ["Uncertainty is part of every measurement.", "Significant figures encode precision honestly.", "Systematic error = bias; random error = scatter.", "Blunders are eliminated, not propagated.", "Propagation rules differ for +/- vs x/divide."], "reqs": ["Instrument precision specifications.", "Replicate measurements.", "Calibration status."], "stds": ["SI units throughout.", "Significant-figure conventions in reporting."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Taylor JR. An Introduction to Error Analysis. 2nd ed. University Science; 1996."], "demo": "#!/usr/bin/env python3\n\"\"\"Propagate relative uncertainty in multiplication.\"\"\"\ndef rel_unc(value, abs_unc):\n    return abs_unc / value\n# concentration = mass/volume\nru = (rel_unc(0.5000, 0.0002)**2 + rel_unc(100.0, 0.08)**2)**0.5\nprint(f\"  relative uncertainty: {ru*100:.2f}%\")\n"}, {"tier": "Foundations", "g": "Data", "title": "Precision vs Accuracy", "desc": "Precision is reproducibility - tight clustering of replicates. Accuracy is closeness to the true value. Four archers: precise and accurate (all in the bullseye), precise but inaccurate (tight group off target - bias), accurate but imprecise (scattered around the bullseye), neither.\nStandard deviation quantifies precision; comparison to a certified reference material tests accuracy. Good analysis needs both - and the two are improved by different actions: replication for precision, calibration and blanks for accuracy.", "how": "Assess precision from replicate standard deviation (n ≥ 3, preferably 5+). Test accuracy against certified reference materials or by spike recovery (target 95-105%). If precise but biased, hunt the systematic error: recalibrate, check blanks, verify standards.", "keys": ["Precision = reproducibility; accuracy = truth-closeness.", "Standard deviation measures precision.", "Reference materials test accuracy.", "Replication improves precision; calibration improves accuracy.", "Precise-but-biased means systematic error."], "reqs": ["Replicate measurements (n≥3).", "Certified reference material.", "Spike-recovery data."], "stds": ["Standard deviation with n stated.", "Recovery acceptance typically 95-105%."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Precision (RSD) vs accuracy (bias) demo.\"\"\"\nimport statistics\nreps = [10.02, 10.05, 10.01, 10.04, 10.03]\ntrue = 10.00\nmean = statistics.mean(reps)\nprint(f\"  mean {mean:.3f}, sd {statistics.stdev(reps):.4f}, bias {mean-true:+.3f}\")\n"}, {"tier": "Foundations", "g": "Data", "title": "Statistical Treatment of Data", "desc": "Means summarize, standard deviations spread, and confidence intervals say what the mean is worth: x̄ ± ts/√n. The t-test asks whether two means differ significantly; the F-test compares precisions; the Q-test (used sparingly, with justification) flags outliers.\nStatistics never rescue bad data - they quantify good data. Report the mean, standard deviation, n, and confidence interval; never silently drop outliers. Detection decisions (is it there?) and quantification use the blank's statistics, not wishful thinking.", "how": "Compute x̄, s, and the 95% confidence interval (t·s/√n). Compare means with the t-test at 95% confidence; compare variances with the F-test. Apply the Q-test to a suspect outlier only once, and report the decision. Base detection limits on blank standard deviation (3s) and quantitation on 10s.", "keys": ["Mean ± t·s/√n: the confidence interval.", "t-test compares means; F-test compares variances.", "Q-test for outliers - used rarely, always reported.", "Statistics quantify good data; they never fix bad data.", "3s = detection, 10s = quantitation."], "reqs": ["Replicate data (n stated).", "t-table values for the confidence level.", "Documented outlier policy."], "stds": ["95% confidence intervals standard.", "Outlier rejection always disclosed."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Miller JN, Miller JC. Statistics and Chemometrics. 6th ed. Pearson; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"95% confidence interval for a mean.\"\"\"\nimport statistics\ndata = [10.02, 10.05, 10.01, 10.04, 10.03]\nmean = statistics.mean(data)\ns = statistics.stdev(data)\nt = 2.776  # t(0.05, 4 df)\nci = t*s/(len(data)**0.5)\nprint(f\"  mean {mean:.3f} ± {ci:.4f} (95% CI, n=5)\")\n"}, {"tier": "Foundations", "g": "Data", "title": "Calibration Curves", "desc": "Instruments measure signals, not concentrations: a calibration curve - signal vs known concentration - translates. Prepare standards spanning the expected range, measure, fit (usually linear least squares), and read unknowns from the line. The correlation coefficient r (or R²) checks linearity; residuals reveal curvature.\nStandard addition handles matrix effects: spike the sample itself with known amounts and extrapolate to zero signal. Internal standards (a constant added compound) correct for injection variability in chromatography - the workhorse quantitation trick.", "how": "Build curves with ≥5 standards bracketing the samples; include a blank. Fit by least squares, inspect residuals for curvature, and never extrapolate beyond the standards. For matrix effects use standard addition; for variable injections use an internal standard and calibrate on response ratios.", "keys": ["Signal → concentration via the calibration line.", "≥5 standards bracketing the samples.", "R² checks linearity; residuals reveal curvature.", "Standard addition beats matrix effects.", "Internal standards correct injection variability."], "reqs": ["Certified standard materials.", "Blank and ≥5 calibration levels.", "Matrix-matched standards or addition."], "stds": ["Least-squares fitting with residuals inspected.", "No extrapolation beyond calibrated range."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Least-squares calibration line.\"\"\"\nxs = [0, 1, 2, 3, 4, 5]\nys = [0.02, 0.21, 0.39, 0.61, 0.79, 1.01]\nn = len(xs)\nslope = (n*sum(a*b for a,b in zip(xs,ys)) - sum(xs)*sum(ys)) / (n*sum(a*a for a in xs) - sum(xs)**2)\nprint(f\"  slope = {slope:.3f} signal units per ppm\")\nprint(f\"  unknown at signal 0.50 -> {0.50/slope:.2f} ppm\")\n"}, {"tier": "Foundations", "g": "Quality", "title": "Quality Assurance and Quality Control", "desc": "QA is the system - documented procedures, trained analysts, calibrated equipment, traceable standards. QC is the evidence - blanks, duplicates, spikes, and control charts proving each batch is in control. Regulated labs (pharma, environmental, forensic) live under GLP/GMP/ISO 17025.\nControl charts plot QC results with warning (±2s) and action (±3s) limits: trends and rule violations (Westgard rules) trigger investigation before bad data ships. Data integrity (ALCOA: attributable, legible, contemporaneous, original, accurate) is non-negotiable.", "how": "Write SOPs for every method; qualify instruments (IQ/OQ/PQ). Chart QC samples per batch; investigate Westgard violations (e.g., 1₃s, 2₂s) before releasing results. Maintain traceability: every standard traces to a certified reference, every result to raw data.", "keys": ["QA = the system; QC = the batch evidence.", "Control charts with ±2s/±3s limits.", "Westgard rules flag out-of-control runs.", "GLP/GMP/ISO 17025 govern regulated labs.", "ALCOA: data integrity principles."], "reqs": ["Written SOPs and training records.", "QC samples with every batch.", "Traceable standards."], "stds": ["ISO 17025 for testing labs.", "Westgard rules for chart interpretation."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Westgard JO. Basic QC Practices. 4th ed. Westgard QC; 2016."], "demo": "#!/usr/bin/env python3\n\"\"\"Control-chart limit check (Westgard 1_3s).\"\"\"\nmean, s = 100.0, 2.0\nqc = [101.5, 99.0, 107.2, 100.5]\nfor v in qc:\n    flag = \"VIOLATION 1_3s\" if abs(v-mean) > 3*s else (\"warning 1_2s\" if abs(v-mean) > 2*s else \"ok\")\n    print(f\"  QC {v}: {flag}\")\n"}, {"tier": "Foundations", "g": "Sampling", "title": "Sampling and Sample Preparation", "desc": "Samples must represent the whole: grab samples snapshot one point, composite samples average over time/space. Preserve them - acidify waters for metals, chill organics, exclude air for redox species - because the analyte changes after collection.\nPreparation dissolves, extracts, or digests: acid digestion (HNO3/HCl) for metals in solids, liquid-liquid or solid-phase extraction to concentrate organics, filtration to remove particulates. Every preparation step is a chance for loss or contamination - validated with spikes.", "how": "Choose grab vs composite by the question asked. Preserve immediately per analyte class. Digest solids with validated acid programs (microwave digestion is standard); extract organics by SPE or LLE; filter at 0.45 µm for dissolved vs total fractions. Validate recovery with matrix spikes.", "keys": ["Representative sampling or nothing else matters.", "Preserve immediately: acidify, chill, exclude air.", "Digestion for solids; extraction for organics.", "Filtration defines dissolved vs total.", "Validate every prep step with spikes."], "reqs": ["Sampling plan with rationale.", "Preservation protocol per analyte.", "Validated digestion/extraction."], "stds": ["Standard preservation (e.g., pH<2 for metals).", "0.45 µm filtration for dissolved fractions."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "EPA. Sample preservation guidance (40 CFR 136)."], "demo": "#!/usr/bin/env python3\n\"\"\"Dilution factor calculator.\"\"\"\ndef dilution(v_sample, v_final):\n    return v_final / v_sample\nprint(f\"  1 mL to 100 mL: DF = {dilution(1, 100):.0f}\")\nprint(f\"  measured 2.5 ppm -> original {2.5*dilution(1,100):.0f} ppm\")\n"}, {"tier": "Foundations", "g": "Classical", "title": "Gravimetric Analysis", "desc": "Gravimetry weighs the analyte: precipitate it selectively, filter, dry or ignite to a known composition, weigh. AgCl for chloride, BaSO4 for sulfate - the precipitates are chosen for low solubility, filterability, and known stoichiometry.\nIt is slow but supremely accurate - no standards needed, just a balance. Coprecipitation is the enemy: impurities trapped in the precipitate bias high. Digestion (heating in mother liquor) grows larger, purer crystals; ignition converts to the weighing form.", "how": "Precipitate from dilute, hot solution with slow reagent addition; digest to coarsen crystals. Filter, wash free of coprecipitated ions, dry/ignite to constant mass. Compute analyte from gravimetric factor (analyte MW / precipitate MW). Run blanks for filter ash.", "keys": ["Weigh the analyte as a pure precipitate.", "No calibration standards needed - just a balance.", "Digestion grows purer, larger crystals.", "Gravimetric factor converts mass to analyte.", "Coprecipitation is the main error source."], "reqs": ["Selective precipitant.", "Known, stable weighing form.", "Analytical balance (±0.1 mg)."], "stds": ["Dry/ignite to constant mass.", "Gravimetric factors from atomic weights."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Gravimetric factor: Cl from AgCl.\"\"\"\nMW_Cl, MW_AgCl = 35.45, 143.32\ngf = MW_Cl / MW_AgCl\nmass_ppt = 0.5000\nprint(f\"  gravimetric factor: {gf:.4f}\")\nprint(f\"  {mass_ppt} g AgCl -> {mass_ppt*gf:.4f} g Cl\")\n"}, {"tier": "Foundations", "g": "Classical", "title": "Titrimetry: Principles", "desc": "Titration adds a standard reagent (titrant) until reaction with the analyte is complete - the equivalence point, detected by an indicator's color change or an instrument (pH, potential). The titrant's concentration is known exactly; the volume delivered gives moles of analyte.\nRequirements: the reaction must be fast, complete (large K), and have a detectable endpoint; the titrant must be a primary standard or standardized against one. Primary standards (KHP, Na2CO3) are pure, stable, high-MW, and react stoichiometrically.", "how": "Standardize the titrant against a primary standard. Titrate to the endpoint matching the equivalence point (indicator pKa near the equivalence pH). Read the burette to ±0.02 mL; compute analyte from M_titrant × V_titrant × stoichiometric ratio. Run blanks and replicates.", "keys": ["Equivalence point: stoichiometric completion.", "Endpoint: the observed signal - match them.", "Primary standards anchor the concentration.", "Reaction must be fast, complete, detectable.", "Burette precision: ±0.02 mL."], "reqs": ["Standardized titrant.", "Suitable indicator or instrumental detection.", "Fast, quantitative reaction."], "stds": ["Primary-standard criteria (purity, stability).", "Endpoint within 0.1 mL of equivalence."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Titration calculation: analyte molarity.\"\"\"\nM_titrant, V_titrant_L, V_analyte_L = 0.1000, 0.02435, 0.02500\nM_analyte = M_titrant * V_titrant_L / V_analyte_L\nprint(f\"  M_analyte = {M_analyte:.4f} M\")\n"}, {"tier": "Foundations", "g": "Classical", "title": "Acid-Base Titrations", "desc": "Strong acid vs strong base: the equivalence pH is 7, with a steep jump of ~6 pH units - any indicator spanning the jump works. Weak acid vs strong base: equivalence is basic (pH > 7, the conjugate base hydrolyzes); choose phenolphthalein, not methyl orange.\nTitration curves plot pH vs volume: the inflection is the equivalence point, and the flat buffer region before it has slope related to buffer capacity. Polyprotic acids (H3PO4, H2CO3) show multiple jumps - each proton titrated in turn, if the Ka values differ enough.", "how": "Sketch the expected curve: compute initial pH, buffer-region pH (Henderson-Hasselbalch), equivalence pH (salt hydrolysis), and excess-titrant pH. Select the indicator whose transition brackets the equivalence pH. For polyprotic systems, titrate each endpoint separately with matched indicators.", "keys": ["Strong-strong: equivalence pH 7, huge jump.", "Weak acid-strong base: equivalence pH > 7.", "Indicator transition must bracket equivalence pH.", "Buffer region follows Henderson-Hasselbalch.", "Polyprotic acids give multiple endpoints."], "reqs": ["Ka values of the acid.", "Indicator transition ranges.", "Carbonate-free base (for accuracy)."], "stds": ["pH meter calibrated with buffers.", "Indicator choice justified by curve."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Henderson-Hasselbalch pH in the buffer region.\"\"\"\nimport math\ndef ph(pka, base, acid):\n    return pka + math.log10(base/acid)\nprint(f\"  acetate buffer 1:1, pKa 4.76: pH = {ph(4.76, 1, 1):.2f}\")\nprint(f\"  acetate buffer 10:1: pH = {ph(4.76, 10, 1):.2f}\")\n"}, {"tier": "Compounded", "g": "Classical", "title": "Redox Titrations", "desc": "Redox titrations use electron transfer: permanganate (MnO4-, self-indicating purple to colorless), dichromate (orange to green Cr3+), iodine/thiosulfate (starch indicator, deep blue to colorless), and cerium(IV). Pretreatment sets the oxidation state: Fe2+ is titrated directly; Fe3+ must first be reduced (SnCl2 or Jones reductor).\nIodometry is indirect: oxidants liberate I2 from I-, then thiosulfate titrates the iodine - the standard for dissolved oxygen (Winkler), peroxides, and vitamin C. Starch goes in near the endpoint, not at the start, or the complex is slow to reverse.", "how": "Choose oxidant by E° and selectivity; ensure the analyte is in the right state first. Add starch near the endpoint for iodometry. Compute from electron stoichiometry (equivalents = moles × n electrons). Standardize permanganate against sodium oxalate - it is not a primary standard (MnO2 forms).", "keys": ["Permanganate: self-indicating; dichromate: primary standard.", "Iodometry: liberate I2, titrate with thiosulfate.", "Starch added near the endpoint only.", "Pretreatment sets the analyte oxidation state.", "Equivalents = moles × electrons transferred."], "reqs": ["Analyte in a single oxidation state.", "Standardized oxidant/reductant.", "Endpoint detection matched to chemistry."], "stds": ["E° values cited for couples.", "Iodometric starch timing specified."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Redox equivalents: Fe2+ by MnO4- (5 e- per MnO4-).\"\"\"\nmoles_MnO4 = 0.1000 * 0.02000\nmoles_Fe = moles_MnO4 * 5\nprint(f\"  Fe2+ titrated: {moles_Fe*1000:.2f} mmol\")\n"}, {"tier": "Compounded", "g": "Classical", "title": "Complexometric Titrations (EDTA)", "desc": "EDTA chelates metal ions 1:1 with huge formation constants, titrating Ca2+, Mg2+ (water hardness), Zn2+, and dozens more. Metallochromic indicators (Eriochrome Black T, wine-red to blue) signal the endpoint by switching from indicator-metal to free indicator color.\npH control is critical: EDTA's conditional formation constant falls at low pH (proton competition). Masking agents (CN- for heavy metals, triethanolamine for Fe3+) let one metal be titrated in a mixture - selectivity by chemistry, not instruments. Water hardness by EDTA is the classic undergraduate lab.", "how": "Buffer to the optimal pH (NH3/NH4+ pH 10 for Ca/Mg). Add masking agents for interferents. Titrate to the indicator color change; compute 1:1 stoichiometry. For mixtures, titrate sequentially with masking, or back-titrate metals that lack good indicators.", "keys": ["EDTA chelates metals 1:1.", "Eriochrome Black T: wine-red to blue endpoint.", "pH controls the conditional formation constant.", "Masking agents give selectivity in mixtures.", "Water hardness = Ca2+ + Mg2+ by EDTA."], "reqs": ["pH buffer matched to metal.", "Metallochromic indicator.", "Masking for interferents."], "stds": ["Conditional constants at working pH.", "Hardness as mg/L CaCO3."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Schwarzenbach G. Complexometric Titrations. 2nd ed. Methuen; 1969."], "demo": "#!/usr/bin/env python3\n\"\"\"Water hardness as mg/L CaCO3.\"\"\"\nM_EDTA, V_L = 0.0100, 0.01240\nmoles = M_EDTA * V_L\nmg_CaCO3 = moles * 100.09 * 1000\nprint(f\"  50 mL sample: hardness = {mg_CaCO3/0.050:.0f} mg/L as CaCO3\")\n"}, {"tier": "Compounded", "g": "Classical", "title": "Precipitation Titrations", "desc": "Silver nitrate titrates halides: Ag+ + Cl- → AgCl(s). The Mohr method uses chromate indicator (red Ag2CrO4 at the endpoint); Volhard back-titrates excess Ag+ with thiocyanate (Fe3+ indicator, red FeSCN2+); Fajans uses adsorption indicators (fluorescein) that change color on the precipitate surface.\nRequirements: the precipitate must form fast and quantitatively (low Ksp), and the endpoint must be visible. pH matters - chromate needs neutral solution (CrO4^2-/Cr2O7^2- equilibrium). Chloride in water and pharmaceuticals is the routine application.", "how": "Choose Mohr (neutral pH, chromate), Volhard (acidic, back-titration), or Fajans (adsorption indicator) by matrix. Control pH for Mohr. Titrate to the first permanent color; compute 1:1 (Ag+:X-) stoichiometry. Protect silver solutions from light.", "keys": ["Ag+ titrates halides; Ksp drives completion.", "Mohr: chromate indicator, neutral pH.", "Volhard: back-titration, acidic, Fe3+ indicator.", "Fajans: adsorption indicators on the precipitate.", "pH control essential for Mohr."], "reqs": ["Low-Ksp precipitate.", "pH matched to method.", "Light-protected silver solutions."], "stds": ["Ksp values cited.", "Indicator method named (Mohr/Volhard/Fajans)."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Fundamentals of Analytical Chemistry. 10th ed. Cengage; 2021."], "demo": "#!/usr/bin/env python3\n\"\"\"Chloride by Mohr titration.\"\"\"\nM_Ag, V_L = 0.1000, 0.01520\nmoles_Cl = M_Ag * V_L\nprint(f\"  Cl- in sample: {moles_Cl*35.45*1000:.1f} mg\")\n"}, {"tier": "Compounded", "g": "Electroanalysis", "title": "Electroanalytical Methods: Potentiometry", "desc": "Potentiometry measures voltage at zero current: the Nernst equation converts potential to activity. The glass pH electrode (H+-selective membrane, ~59 mV/pH at 25 °C) is the most used sensor in chemistry; ion-selective electrodes (fluoride, calcium, nitrate) extend it.\nReference electrodes (Ag/AgCl, calomel) complete the cell with a stable potential. Calibrate with buffers bracketing the sample; temperature matters (slope is T-dependent). Potentiometric titrations find endpoints from the potential jump - no indicator needed.", "how": "Calibrate ISEs with standards bracketing samples; check slope (Nernstian: 59.2/z mV/decade at 25 °C). Maintain constant ionic strength (TISAB for fluoride). For titrations, plot E vs V and take the inflection (or Gran plot) as the endpoint. Store glass electrodes in solution, never dry.", "keys": ["Nernst equation converts potential to activity.", "Glass electrode: ~59 mV per pH at 25 C.", "Reference electrodes anchor the cell potential.", "ISEs: fluoride, calcium, nitrate and more.", "Potentiometric titrations need no indicator."], "reqs": ["Calibrated ISE and reference electrode.", "Constant ionic strength.", "Temperature control or compensation."], "stds": ["Nernstian slope check reported.", "pH buffers traceable (NIST)."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000."], "demo": "#!/usr/bin/env python3\n\"\"\"Nernstian slope at 25 C.\"\"\"\nimport math\nslope = 2.303*8.314*298.15/96485*1000\nprint(f\"  slope = {slope:.1f} mV per decade (z=1)\")\nprint(f\"  pH slope = {slope:.1f} mV per pH unit\")\n"}, {"tier": "Compounded", "g": "Electroanalysis", "title": "Voltammetry and Amperometry", "desc": "Voltammetry sweeps potential and measures current: the peak position identifies the species, the peak height quantifies it. Cyclic voltammetry's duck-shaped curves diagnose reversibility - ΔEp ≈ 59/n mV for reversible couples - and map reaction mechanisms.\nAmperometry holds potential and measures current vs time: the Clark oxygen electrode and glucose biosensors (glucose oxidase + H2O2 detection) are amperometric. Stripping voltammetry preconcentrates metals onto the electrode, reaching ppt detection limits for Pb, Cd, Zn.", "how": "Choose CV for mechanism diagnosis, differential-pulse or stripping for trace quantitation. Deoxygenate for reductions (O2 interferes). For amperometric sensors, immobilize the enzyme/biorecognition layer and calibrate in matrix. Report peak potentials vs the reference used.", "keys": ["Peak position identifies; peak height quantifies.", "CV reversibility: ΔEp ≈ 59/n mV.", "Amperometry: glucose sensors, O2 electrodes.", "Stripping voltammetry reaches ppt metals.", "Deoxygenate for reductive scans."], "reqs": ["Three-electrode cell with reference.", "Deoxygenated solution for reductions.", "Supporting electrolyte."], "stds": ["Potentials vs stated reference.", "Scan rates reported for CV."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Randles-Sevcik peak current vs scan rate.\"\"\"\ndef ip(scan_rate, k=1.0):\n    return k * scan_rate**0.5\nfor v in (0.01, 0.05, 0.1, 0.5):\n    print(f\"  v={v:.2f} V/s: ip = {ip(v):.3f} (relative)\")\n"}, {"tier": "Compounded", "g": "Spectroscopy", "title": "Introduction to Spectroscopy for Analysis", "desc": "Spectroscopy measures light-matter interaction: absorption (Beer-Lambert: A = εbc), emission (fluorescence, atomic emission), and scattering. Each region probes different energies - UV-vis for electronic transitions, IR for vibrations, NMR for nuclear spins.\nQuantitation rests on Beer-Lambert: absorbance proportional to concentration and path length, within the linear range. Deviations come from stray light, polychromatic radiation, and chemical equilibria shifting with concentration - know the law's limits.", "how": "Select wavelength at maximum absorbance for sensitivity. Verify linearity over the working range; dilute samples into it. Use matched cuvettes and blank correction. For mixtures, measure at multiple wavelengths and solve simultaneous equations (multi-component analysis).", "keys": ["A = εbc: the quantitative workhorse.", "Absorption, emission, scattering: three signal types.", "Regions probe different molecular energies.", "Linear range verified, not assumed.", "Multi-wavelength solves mixtures."], "reqs": ["Wavelength of maximum absorbance.", "Linear-range verification.", "Matched cuvettes, blank correction."], "stds": ["ε in M⁻¹cm⁻¹, path length in cm.", "Wavelengths in nm."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Beer-Lambert: A = eps*b*c.\"\"\"\ndef absorbance(eps, b, c):\n    return eps*b*c\nprint(f\"  eps=5000, b=1 cm, c=2e-5 M: A = {absorbance(5000, 1, 2e-5):.3f}\")\n"}, {"tier": "Compounded", "g": "Spectroscopy", "title": "UV-Visible Spectrophotometry", "desc": "UV-vis (190-800 nm) excites electronic transitions: conjugated pi systems absorb strongly (butadiene 217 nm, β-carotene 450 nm - its orange color). It quantifies anything absorbing - or made to absorb via derivatization - from proteins (280 nm) to metal complexes.\nInstruments: deuterium (UV) + tungsten (vis) lamps, monochromator or diode array, sample/reference beams. Diode arrays capture full spectra in milliseconds - ideal for chromatography detectors and kinetics. Colorimetry is UV-vis with the human eye replaced by the detector.", "how": "Scan the full spectrum to find λmax; quantitate there. Derivatize non-absorbers (ninhydrin for amino acids). Use diode-array detection for peak-purity checks in HPLC. Correct baselines; keep absorbance 0.1-1.0 for best precision.", "keys": ["Electronic transitions; conjugation shifts λmax red.", "λmax chosen for sensitivity.", "Diode arrays: full spectra in milliseconds.", "Derivatization extends it to non-absorbers.", "Keep A in 0.1-1.0 for precision."], "reqs": ["λmax from a full scan.", "Transparent solvents at working λ.", "Baseline correction."], "stds": ["λmax in nm with solvent stated.", "Absorbance range 0.1-1.0 preferred."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Skoog DA et al. Principles of Instrumental Analysis. 7th ed. Cengage; 2017."], "demo": "#!/usr/bin/env python3\n\"\"\"Conjugation vs lambda-max trend.\"\"\"\ndata = [(\"ethene\", 1, 165), (\"butadiene\", 2, 217), (\"beta-carotene\", 11, 450)]\nfor name, db, lam in data:\n    print(f\"  {name:13s} {db:2d} double bonds: {lam} nm\")\n"}, {"tier": "Compounded", "g": "Spectroscopy", "title": "Atomic Absorption and Emission", "desc": "Atomic spectroscopy atomizes the sample (flame ~2300 °C, graphite furnace, or ICP plasma ~8000 K) and measures element-specific light: AAS absorbs from hollow-cathode lamps (one element per lamp), AES/ICP-OES measures emission from the plasma - multi-element at ppb levels.\nICP-MS pushes to ppt with mass-spectrometric detection - the gold standard for trace metals in water, blood, and food. Interferences (spectral overlaps, matrix effects) are managed with background correction, internal standards, and collision cells.", "how": "Choose flame AAS for ppm single elements, graphite furnace for ppb single, ICP-Oes for multi-element ppb, ICP-MS for ppt. Matrix-match standards or use standard addition. Run blanks obsessively - contamination dominates trace-metal error. Validate with CRMs.", "keys": ["Atomize, then measure element-specific light.", "Flame AAS: ppm; furnace: ppb; ICP-OES: multi-element ppb.", "ICP-MS: the ppt gold standard.", "Hollow-cathode lamps: one element each.", "Contamination control dominates trace work."], "reqs": ["Atomization source matched to level.", "Background correction.", "Matrix-matched calibration."], "stds": ["Detection limits with method stated.", "CRM validation for trace claims."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Welz B, Sperling M. Atomic Absorption Spectrometry. 3rd ed. Wiley-VCH; 1999."], "demo": "#!/usr/bin/env python3\n\"\"\"Technique selection by required level.\"\"\"\ndef technique(ppb_needed):\n    if ppb_needed < 0.1: return \"ICP-MS\"\n    if ppb_needed < 10: return \"graphite furnace AAS or ICP-OES\"\n    return \"flame AAS\"\nfor level in (0.01, 1, 100):\n    print(f\"  need {level} ppb -> {technique(level)}\")\n"}, {"tier": "Compounded", "g": "Separations", "title": "Introduction to Chromatography", "desc": "Chromatography separates by differential partitioning between a stationary phase and a mobile phase: compounds that linger on the stationary phase elute later. Plate theory (N theoretical plates) and rate theory (van Deemter: eddy diffusion, longitudinal diffusion, mass transfer) quantify efficiency.\nResolution Rs = Δt/w̄ must exceed 1.5 for baseline separation. Retention factor k, selectivity α, and plate count N combine: Rs ∝ √N · (α-1)/α · k/(1+k) - the master equation guiding every method development.", "how": "Optimize in order: selectivity (phase chemistry) first, then retention (solvent strength), then efficiency (particle size, flow). Target k 2-10, α > 1.1, Rs ≥ 1.5. Diagnose band broadening with the van Deemter curve - find the optimal flow rate at its minimum.", "keys": ["Separation by differential partitioning.", "Rs ≥ 1.5 = baseline separation.", "Master equation: Rs from N, α, k.", "van Deemter optimizes flow rate.", "Selectivity first, then retention, then efficiency."], "reqs": ["Stationary/mobile phase pair.", "Retention data for k and α.", "Efficiency (plates) measured."], "stds": ["Rs ≥ 1.5 for baseline separation.", "k reported with conditions."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Snyder LR et al. Introduction to Modern Liquid Chromatography. 3rd ed. Wiley; 2010."], "demo": "#!/usr/bin/env python3\n\"\"\"Resolution from retention times and widths.\"\"\"\ndef resolution(t1, t2, w1, w2):\n    return 2*(t2-t1)/(w1+w2)\nprint(f\"  t=5.0/5.5 min, w=0.2: Rs = {resolution(5.0, 5.5, 0.2, 0.2):.2f}\")\n"}, {"tier": "Compounded", "g": "Separations", "title": "Gas Chromatography", "desc": "GC separates volatiles on a capillary column (30 m × 0.25 mm) with He carrier gas: compounds partition into the stationary phase (polysiloxane films) and elute by boiling point and polarity. Temperature programming ramps the oven to elute wide boiling ranges.\nDetectors: FID (universal for organics, pg sensitivity), TCD (universal), ECD (halogens, ultra-sensitive), MS (identification). GC-MS is the forensic and environmental workhorse - arson, drugs, pesticides. Derivatization extends GC to polar analytes.", "how": "Choose column polarity to match analytes; program temperature for the boiling range. Use split/splitless injection appropriately (splitless for traces). Quantitate with internal standards; confirm identity by retention time + MS spectrum. Derivatize acids/amines (silylation) for volatility.", "keys": ["Capillary columns; He carrier; temperature programming.", "FID: universal organics; ECD: halogens; MS: identity.", "GC-MS: the forensic/environmental workhorse.", "Derivatization volatilizes polar analytes.", "Internal standards for quantitation."], "reqs": ["Volatile or derivatizable analytes.", "Column polarity matched.", "Carrier-gas purity."], "stds": ["Retention times with conditions.", "MS confirmation for identity."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "McMaster MC. GC/MS: A Practical User Guide. 2nd ed. Wiley; 2007."], "demo": "#!/usr/bin/env python3\n\"\"\"GC elution order by boiling point (nonpolar column).\"\"\"\nanalytes = [(\"hexane\", 69), (\"toluene\", 111), (\"naphthalene\", 218)]\nfor name, bp in sorted(analytes, key=lambda a: a[1]):\n    print(f\"  {name:12s} bp {bp} C elutes in order\")\n"}, {"tier": "Compounded", "g": "Separations", "title": "Liquid Chromatography (HPLC)", "desc": "HPLC pumps solvent through packed columns (3-5 µm particles, up to 400 bar; UHPLC smaller, higher pressure) separating non-volatiles: drugs, proteins, natural products. Reversed-phase (C18 + water/acetonitrile gradient) dominates - nonpolar analytes retained longest.\nDetectors: UV (universal for chromophores), fluorescence (sensitive), MS (identification), ELSD/CAD (universal). Gradient elution ramps solvent strength for wide polarity ranges. Method development tunes selectivity via pH, organic modifier, and column chemistry.", "how": "Start reversed-phase C18 with water/acetonitrile gradient; adjust pH to control ionization (±2 units from pKa). Optimize selectivity before efficiency. Validate: linearity, precision, accuracy, LOD/LOQ, robustness per ICH Q2. Use guard columns to protect the analytical column.", "keys": ["Reversed-phase C18 dominates pharmaceutical analysis.", "Gradient elution handles wide polarity ranges.", "pH controls retention of ionizable analytes.", "UHPLC: smaller particles, faster, higher pressure.", "Validation per ICH Q2 guidelines."], "reqs": ["Column chemistry and dimensions.", "Mobile-phase pH and gradient.", "Detector matched to analytes."], "stds": ["ICH Q2 validation parameters.", "Pressures in bar with particle size."], "cites": ["Snyder LR et al. Introduction to Modern Liquid Chromatography. 3rd ed. Wiley; 2010.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Retention factor from dead time and retention time.\"\"\"\ndef k(tR, t0):\n    return (tR - t0)/t0\nfor tR in (3.0, 6.0, 12.0):\n    print(f\"  tR={tR} min, t0=1.0: k = {k(tR, 1.0):.1f}\")\n"}, {"tier": "Compounded", "g": "Separations", "title": "Mass Spectrometry Basics", "desc": "MS weighs ions: ionize (EI at 70 eV fragments hard; ESI/APCI softly for LC), separate by m/z (quadrupole, time-of-flight, Orbitrap), detect. The molecular ion gives MW; fragments give structure; isotope patterns (Br 1:1, Cl 3:1) count halogens.\nHigh resolution (Orbitrap, FT-ICR) measures mass to ppm, yielding elemental composition directly. Tandem MS (MS/MS) fragments selected ions for structure - proteomics sequences peptides this way. GC-MS and LC-MS hyphenation made MS the identifier behind every separation.", "how": "Choose ionization: EI for volatile GC analytes (library searchable), ESI for LC biomolecules. Read the molecular ion (watch for adducts: [M+H]+, [M+Na]+ in ESI), interpret fragments by neutral losses, and use isotope patterns for formula constraints. Confirm with high-res exact mass.", "keys": ["Ionize, separate by m/z, detect.", "EI fragments hard (libraries); ESI softly (biomolecules).", "Isotope patterns count halogens (Br 1:1, Cl 3:1).", "High-res MS gives elemental composition.", "MS/MS fragments selected ions for structure."], "reqs": ["Ionization matched to analyte.", "Calibrated mass axis.", "Adduct awareness in soft ionization."], "stds": ["m/z with charge state.", "Mass accuracy in ppm for HRMS."], "cites": ["McLafferty FW, Turecek F. Interpretation of Mass Spectra. 4th ed. University Science; 1993.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Chlorine isotope pattern (35Cl:37Cl = 3:1).\"\"\"\nprint(\"  CH2Cl2 molecular ion cluster:\")\nprint(\"  m/z 84 (35,35): 9 parts; m/z 86 (35,37): 6 parts; m/z 88 (37,37): 1 part\")\n"}, {"tier": "Advanced", "g": "Spectroscopy", "title": "NMR for Quantitative Analysis", "desc": "qNMR quantifies without analyte-specific standards: signal area is proportional to nuclei count, so one internal standard (maleic acid, DSS) calibrates everything. It assays drugs, natural products, and reaction yields with primary-method accuracy.\nRequirements: full relaxation between pulses (D1 ≥ 5×T1), clean baseline, resolved signals, and known proton counts. ¹H qNMR is routine; ¹⁹F/³¹P extend it. The method is in pharmacopeias for absolute quantitation - no calibration curve needed.", "how": "Weigh sample + internal standard accurately. Set D1 ≥ 5×T1 (measure or use 30 s default), acquire with good S/N, phase and baseline-correct carefully. Integrate clean signals; compute purity from area ratios, proton counts, and molecular weights.", "keys": ["Signal area ∝ nuclei: one standard quantifies all.", "No analyte calibration curve needed.", "D1 ≥ 5×T1 for full relaxation.", "Pharmacopeial primary method.", "Baseline and phasing quality decide accuracy."], "reqs": ["Internal standard (purity known).", "Relaxation delay verified.", "Resolved, clean signals."], "stds": ["D1 ≥ 5×T1 documented.", "Purity with uncertainty."], "cites": ["Malz F, Jancke H. J Pharm Biomed Anal 2005;38:813-823.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"qNMR purity calculation.\"\"\"\nA_samp, A_std = 3.42, 2.00\nH_samp, H_std = 3, 2\nMW_samp, MW_std = 180.16, 116.07\nm_std, m_samp = 10.0, 12.0\npurity = (A_samp/A_std)*(H_std/H_samp)*(MW_samp/MW_std)*(m_std/m_samp)\nprint(f\"  purity = {purity*100:.1f}%\")\n"}, {"tier": "Advanced", "g": "Hyphenated", "title": "Hyphenated Techniques (GC-MS, LC-MS)", "desc": "Hyphenation marries separation to identification: GC-MS (EI libraries of 300k+ spectra) screens drugs, pesticides, and arson accelerants; LC-MS/MS (triple quadrupole, MRM) quantifies pharmaceuticals and biomarkers at ppt with exquisite selectivity.\nInterfaces matter: GC-MS needs vacuum-compatible flow (jet separators are history - capillary columns feed directly); LC-MS needs atmospheric-pressure ionization (ESI/APCI) to bridge liquid to vacuum. High-res LC-MS (Orbitrap) adds formula confirmation to every peak.", "how": "Match ionization to the separation: EI for GC, ESI/APCI for LC. For quantitation use MRM on triple quads with stable-isotope internal standards. Confirm identity by retention time + two MRM transitions (EU: ion-ratio tolerances). Validate matrix effects by post-column infusion.", "keys": ["GC-MS: EI libraries identify unknowns.", "LC-MS/MS MRM: ppt quantitation with selectivity.", "Interfaces bridge separation to vacuum.", "Stable-isotope internal standards are ideal.", "Retention + spectra + ratios confirm identity."], "reqs": ["Ionization matched to mobile phase.", "Internal standard (isotopic preferred).", "Matrix-effect evaluation."], "stds": ["Two MRM transitions for confirmation.", "Ion-ratio tolerances per regulation."], "cites": ["McMaster MC. GC/MS: A Practical User Guide. 2nd ed. Wiley; 2007.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"MRM transition picker (toy data).\"\"\"\ntransitions = [(\"precursor 300\", \"product 150\", 100), (\"precursor 300\", \"product 122\", 60)]\nfor prec, prod, inten in transitions:\n    role = \"quantifier\" if inten == 100 else \"qualifier\"\n    print(f\"  {prec} -> {prod}: {role}\")\n"}, {"tier": "Advanced", "g": "Validation", "title": "Method Validation", "desc": "Validation proves a method fit for purpose: specificity, linearity, range, accuracy, precision (repeatability + intermediate), detection/quantitation limits, and robustness (ICH Q2). Pharma methods are validated before GMP use; environmental methods per EPA protocols.\nSystem suitability tests (SST) run daily: plate count, tailing, resolution, RSD of replicate standards - the method re-proves itself every sequence. Revalidation follows any change in method, column, or instrument.", "how": "Execute the ICH Q2 parameter set with acceptance criteria set before the study. Document everything; deviations invalidate. Implement SST limits in the SOP and enforce them - a failing SST means no sample results ship. Revalidate after changes.", "keys": ["ICH Q2: the validation parameter set.", "Acceptance criteria set before the study.", "System suitability re-proves the method daily.", "Revalidate after any method change.", "Validation precedes GMP/regulatory use."], "reqs": ["Written validation protocol.", "Pre-set acceptance criteria.", "SST limits in the SOP."], "stds": ["ICH Q2(R2) parameters.", "EPA method protocols where applicable."], "cites": ["ICH Q2(R2). Validation of Analytical Procedures. 2023.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Validation checklist status.\"\"\"\nparams = [\"specificity\", \"linearity\", \"accuracy\", \"precision\", \"LOD/LOQ\", \"robustness\"]\ndone = {\"specificity\", \"linearity\", \"accuracy\"}\nfor p in params:\n    print(f\"  [{\"x\" if p in done else \" \"}] {p}\")\n"}, {"tier": "Advanced", "g": "Validation", "title": "Detection Limits: LOD and LOQ", "desc": "LOD (3σ of the blank, or S/N = 3) is the smallest signal distinguishable from noise - detection, not measurement. LOQ (10σ, S/N = 10) is the smallest quantifiable amount with acceptable precision. Between them lies the twilight zone: detected but not quantified.\nEstimate from blank statistics, calibration-line residuals, or S/N of low standards - then verify by analyzing a standard at the claimed limit. Regulatory methods (EPA MDL) prescribe exact procedures; 'not detected' means below LOD, never zero.", "how": "Measure ≥7 blanks (or low standards), compute σ, set LOD = 3σ/slope, LOQ = 10σ/slope. Verify by analyzing at the LOD (must detect) and LOQ (must meet precision criteria). Report 'ND' as '< LOD', with the LOD value stated.", "keys": ["LOD = 3σ: detected. LOQ = 10σ: quantified.", "Between them: detected, not quantified.", "'Not detected' means < LOD, never zero.", "Verify limits by analyzing at the limit.", "EPA MDL has a prescribed procedure."], "reqs": ["Blank/low-level statistics (n≥7).", "Calibration slope.", "Verification at claimed limits."], "stds": ["LOD/LOQ with estimation method stated.", "EPA 40 CFR 136 App. B for MDL."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "EPA. Definition and Procedure for MDL (40 CFR 136 App. B)."], "demo": "#!/usr/bin/env python3\n\"\"\"LOD/LOQ from blank statistics.\"\"\"\nimport statistics\nblanks = [0.012, 0.008, 0.015, 0.011, 0.009, 0.013, 0.010]\ns = statistics.stdev(blanks)\nslope = 0.50\nprint(f\"  LOD = {3*s/slope:.4f} ppm, LOQ = {10*s/slope:.4f} ppm\")\n"}, {"tier": "Advanced", "g": "Data", "title": "Chemometrics", "desc": "Chemometrics extracts information from multivariate data: PCA compresses spectra into scores plots revealing sample groupings; PLS calibrates overlapping spectra to concentrations (NIR grain analysis); experimental design (factorial, Box-Behnken) optimizes methods with minimal runs.\nIt is statistics for chemical data: preprocessing (baselines, normalization), validation (cross-validation, test sets - never validate on training data), and outlier diagnostics. Modern instruments produce data cubes; chemometrics reads them.", "how": "Preprocess (baseline, normalize, mean-center), explore with PCA, then build PLS/PCR models with cross-validation. Validate on independent test sets; report RMSEP. Design experiments factorially to find optima and interactions with few runs.", "keys": ["PCA explores; PLS calibrates multivariate data.", "Preprocessing decides model quality.", "Cross-validate; test on independent data.", "Experimental design minimizes runs.", "Never validate on training data."], "reqs": ["Multivariate dataset with metadata.", "Preprocessing rationale.", "Independent validation set."], "stds": ["RMSEP/R² reported on test data.", "Design matrices documented."], "cites": ["Miller JN, Miller JC. Statistics and Chemometrics. 6th ed. Pearson; 2010.", "Brereton RG. Chemometrics. Wiley; 2003."], "demo": "#!/usr/bin/env python3\n\"\"\"Variance explained by principal components (toy).\"\"\"\nvariances = [62, 25, 8, 3, 2]\ncum = 0\nfor i, v in enumerate(variances, 1):\n    cum += v\n    print(f\"  PC{i}: {v}% (cumulative {cum}%)\")\n"}, {"tier": "Advanced", "g": "Applied", "title": "Environmental Sampling and Analysis", "desc": "Environmental analysis enforces the Clean Water/Air Acts: BOD/COD for wastewater, metals by ICP-MS, organics by GC-MS/LC-MS/MS, nutrients by colorimetry. Holding times are law - analyze within them or the data is invalid.\nField QC (trip blanks, field duplicates, equipment rinsates) proves sampling integrity. Detection limits must sit below regulatory thresholds - a method that cannot see the limit is useless. Data goes to regulators; defensibility is everything.", "how": "Follow EPA methods verbatim (holding times, preservation, QC frequencies). Collect field blanks and duplicates; keep chain of custody. Ensure LODs below permit limits with margin. Report with qualifiers (J = estimated, U = undetected) per data-validation guidelines.", "keys": ["EPA methods are legally binding procedures.", "Holding times are law.", "Field QC proves sampling integrity.", "LODs must beat regulatory limits.", "Qualifiers (J, U) flag data quality."], "reqs": ["EPA method citation.", "Field QC samples.", "Chain of custody."], "stds": ["40 CFR 136 methods.", "Holding times per method."], "cites": ["EPA. Test Methods (SW-846).", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Holding-time compliance check.\"\"\"\nsamples = [(\"metals\", 6*30, 180), (\"BOD\", 2, 2), (\"VOCs\", 10, 14)]\nfor name, age_days, limit in samples:\n    print(f\"  {name:7s}: age {age_days}d / limit {limit}d -> {\"OK\" if age_days <= limit else \"EXPIRED\"}\")\n"}, {"tier": "Advanced", "g": "Applied", "title": "Trace Analysis and Contamination Control", "desc": "At ppb/ppt, the lab is the sample: dust, reagents, containers, and analysts contaminate. Trace-metal labs use Class-100 clean rooms, acid-washed Teflon, and sub-boiling distilled acids; blanks define what can be claimed.\nPatterson's lead work showed the world was contaminated - including his own lab - forcing the clean techniques that revealed true environmental levels. Every trace result stands on its blank: if the blank is high, the data dies.", "how": "Work clean: acid-wash containers, use high-purity reagents, run method blanks with every batch. Subtract blanks only when small and stable; investigate high blanks instead. Validate at the working level with CRMs; track blank trends on control charts.", "keys": ["At trace levels, the lab is the sample.", "Blanks define what can be claimed.", "Clean rooms and pure reagents for metals.", "Patterson's lead work founded clean techniques.", "High blanks kill data - investigate, don't subtract blindly."], "reqs": ["Method blanks every batch.", "High-purity reagents and containers.", "Blank-trend control charts."], "stds": ["Blank acceptance criteria in SOP.", "CRM validation at working level."], "cites": ["Patterson CC. Geochim Cosmochim Acta 1965;29:1009.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"Blank-limited reporting decision.\"\"\"\nblank, sample = 0.8, 2.5  # ppb\nif blank > 0.5*sample:\n    print(\"  blank too high: investigate, do not report\")\nelse:\n    print(f\"  report {sample-blank:.1f} ppb (blank-corrected)\")\n"}, {"tier": "Advanced", "g": "Electroanalysis", "title": "Electrochemical Sensors", "desc": "Sensors turn chemistry into signals: the glass pH electrode, blood-gas analyzers, glucose test strips (mediated amperometry, billions per year), and ion-selective electrodes for clinical electrolytes. Selectivity comes from membranes (ionophores like valinomycin for K+) or enzymes.\nWearables and field probes extend sensing: dissolved-oxygen probes, heavy-metal screen-printed electrodes for water testing. Calibration drift is the eternal enemy - built-in calibration or single-use designs answer it.", "how": "Choose transduction: potentiometric for ions (Nernstian), amperometric for redox species. Build selectivity with ionophore membranes or enzyme layers. Calibrate frequently; validate against reference methods. For field use, prefer disposable calibrated sensors over maintained ones.", "keys": ["Membranes/enzymes create selectivity.", "Glucose strips: the biggest sensor success.", "Potentiometric for ions; amperometric for redox.", "Calibration drift is the eternal enemy.", "Validate against reference methods."], "reqs": ["Selective recognition element.", "Calibration protocol.", "Reference-method validation."], "stds": ["Selectivity coefficients reported.", "Drift specifications stated."], "cites": ["Bard AJ, Faulkner LR. Electrochemical Methods. 2nd ed. Wiley; 2000.", "Bakker E, Qin Y. Anal Chem 2006;78:3965-3983."], "demo": "#!/usr/bin/env python3\n\"\"\"ISE selectivity: Nikolsky equation (toy).\"\"\"\nimport math\ndef E(E0, a_i, a_j, K, z=1):\n    return E0 + 59.2/z*math.log10(a_i + K*a_j)\nprint(f\"  K+ electrode vs Na+: E = {E(0, 1e-3, 1e-1, 1e-4):.1f} mV\")\n"}, {"tier": "Advanced", "g": "Separations", "title": "Capillary Electrophoresis", "desc": "CE separates ions in a fused-silica capillary under 30 kV: electroosmotic flow sweeps everything to the detector while electrophoretic mobility separates by charge/size. Efficiencies reach millions of plates - DNA sequencing ran on CE.\nModes: CZE (free solution), MEKC (micelles for neutrals), CGE (gels for size), CIEF (isoelectric focusing). Nanoliter injections and minute runs suit bioanalysis; poor concentration sensitivity is the trade-off, fixed by stacking or MS detection.", "how": "Choose buffer pH to set analyte charge and EOF; condition capillaries between runs. Stack samples (field-amplified injection) for sensitivity. Validate migration-time precision - the key CE metric. Couple to MS for identification.", "keys": ["30 kV in capillaries; EOF + mobility separate.", "Millions of plates - DNA sequencing heritage.", "Modes: CZE, MEKC, CGE, CIEF.", "Nanoliter samples, minute runs.", "Stacking fixes concentration sensitivity."], "reqs": ["Fused-silica capillary, conditioned.", "Buffer pH matched to analytes.", "High-voltage safety."], "stds": ["Migration-time RSD reported.", "Plates per meter."], "cites": ["Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020.", "Li SFY. Capillary Electrophoresis. Elsevier; 1992."], "demo": "#!/usr/bin/env python3\n\"\"\"Electrophoretic mobility from migration time.\"\"\"\ndef mobility(Ld, Lt, t, V):\n    return Ld*Lt/(t*V)\nprint(f\"  mu = {mobility(0.5, 0.6, 300, 20000):.2e} m²/Vs\")\n"}, {"tier": "Advanced", "g": "Thermal", "title": "Thermal Analysis Methods", "desc": "TGA weighs a sample vs temperature: weight loss steps reveal water, decomposition, and filler content (CaCO3 → CO2 at ~800 °C). DSC measures heat flow: melting endotherms, crystallization exotherms, glass transitions - polymer crystallinity and drug polymorphs.\nTGA-MS/FTIR identifies evolved gases; DSC purity analysis uses melting-point depression (van't Hoff). Pharma uses DSC for polymorph screening - different crystal forms, different bioavailability - and TGA for solvate/hydrate characterization.", "how": "Run TGA in N2 (pyrolysis) and air (oxidation) to separate steps; couple evolved-gas analysis for identity. Use DSC heating/cooling cycles to distinguish reversible (glass transition) from irreversible (decomposition) events. Calibrate temperature with indium/zinc standards.", "keys": ["TGA: mass vs temperature (composition).", "DSC: heat flow (transitions, purity).", "Evolved-gas analysis identifies weight losses.", "Polymorph screening by DSC in pharma.", "Calibrate with metal standards."], "reqs": ["Calibrated temperature and balance.", "Atmosphere control (N2/air).", "Heating-rate specification."], "stds": ["Temperatures in °C with heating rate.", "Mass loss in % with step assignment."], "cites": ["Brown ME. Introduction to Thermal Analysis. 2nd ed. Kluwer; 2001.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"TGA: CaCO3 decomposition mass loss.\"\"\"\nMW_CaCO3, MW_CO2 = 100.09, 44.01\nloss = MW_CO2/MW_CaCO3*100\nprint(f\"  CaCO3 -> CaO + CO2: {loss:.1f}% mass loss\")\n"}, {"tier": "Advanced", "g": "Quality", "title": "Certified Reference Materials and Traceability", "desc": "CRMs (NIST SRMs) are the top of the traceability chain: certified values with uncertainties, produced under ISO 17034. Every calibration standard, and therefore every result, traces up through working standards to a CRM - the unbroken chain that makes measurements comparable worldwide.\nUse matrix-matched CRMs to validate whole methods (digestion included); use pure-substance CRMs to calibrate instruments. Commutability matters in clinical labs - the CRM must behave like real samples in the method.", "how": "Select CRMs matching matrix and level; verify certificates are current. Build the traceability chain: CRM → primary standard → working standard → sample. Validate methods with matrix CRMs; investigate any result outside the certified interval.", "keys": ["CRMs anchor the traceability chain.", "ISO 17034 governs CRM producers.", "Matrix-matched CRMs validate whole methods.", "Unbroken chain: CRM to result.", "Commutability matters clinically."], "reqs": ["Current CRM certificates.", "Matrix and level match.", "Documented traceability chain."], "stds": ["ISO 17034 for CRM producers.", "NIST SRM certificates cited."], "cites": ["NIST. Standard Reference Materials catalog.", "Harris DC. Quantitative Chemical Analysis. 10th ed. Freeman; 2020."], "demo": "#!/usr/bin/env python3\n\"\"\"CRM validation: z-score check.\"\"\"\ndef zscore(measured, certified, u):\n    return (measured-certified)/u\nz = zscore(10.4, 10.0, 0.3)\nprint(f\"  z = {z:.2f} -> {\"PASS\" if abs(z) <= 2 else \"INVESTIGATE\"}\")\n"}];
function buildRecord(seed,topic,sig){
  var title=topic.title+(sig?' (Signature Edition)':'');
  var desc=topic.desc;
  if(sig)desc='Signature original treatment. '+desc;
  return {
    id:(sig?'JAH-ANALCS-':PREFIX)+String(seed).padStart(6,'0'),
    t:title, g:topic.g, name:title, title:title,
    description:desc,
    how_it_works:topic.how,
    key_points:topic.keys,
    requirements:topic.reqs,
    standards:topic.stds,
    citations:topic.cites,
    src:sig?'signature':'public-harvest',
    signature_label:sig?'Signature-generated original treatment - clearly labeled Signature-made and never presented as authentic public record.':'Public-harvest record - real, fact-checked domain knowledge.',
    ladder_rank:seed,
    ladder_tier:topic.tier.toLowerCase(),
    demo:{kind:'python',language:'python',program:topic.demo,
      note:'Working demonstration program for this record.'},
    _seed:seed
  };
}
function topicFor(seed,opts){
  opts=opts||{};
  var pool=TOPICS.filter(function(t){return !opts.field||t.tier===opts.field;});
  if(!pool.length)pool=TOPICS;
  var i=((seed-1)%pool.length+pool.length)%pool.length;
  return {topic:pool[i],index:TOPICS.indexOf(pool[i])};
}
function generate(seed,opts){
  var tf=topicFor(seed,opts);
  var sig=(opts&&opts.signature)||true;
  return buildRecord(tf.index+1,tf.topic,sig);
}
function validate(r){
  var e=[];
  if(!r||typeof r!=='object')return {ok:false,errors:['not an object']};
  var okId=new RegExp('^('+PREFIX.replace(/-/g,'\\-')+'|'+'JAH-ANALCS-'.replace(/-/g,'\\-')+')\\d{6}$').test(r.id||'');
  if(!okId)e.push('id');
  if(FIELDS.indexOf(capTier(r.ladder_tier))<0)e.push('tier');
  if(['public-harvest','signature'].indexOf(r.src)<0)e.push('src');
  if(!r.title)e.push('title');
  if(!r.description||r.description.length<40)e.push('description');
  if(!r.demo||!r.demo.program||r.demo.program.indexOf('print')<0)e.push('demo');
  return {ok:!e.length,errors:e};
}
function capTier(s){s=String(s||'');return s.charAt(0).toUpperCase()+s.slice(1);}
function driftCheck(record,sample){
  var dups=(sample||[]).filter(function(r){return r&&r.title===record.title&&r.ladder_tier===record.ladder_tier;});
  return dups.length?{ok:false,errors:['duplicate title+tier in archive sample']}:{ok:true,errors:[]};
}
var gen={version:'jahdb-analytical-chemistry-signature-1.0',generate:generate,validate:validate,driftCheck:driftCheck,fields:FIELDS};
if(typeof JAHDB!=='undefined'&&JAHDB.registerGenerator)JAHDB.registerGenerator('analytical-chemistry-signature',gen);
if(typeof module!=='undefined'&&module.exports)module.exports=gen;
})();
